modes.detail:
// ============ 为什么要"状态"而不只是"值" ============
//
// 数组里每格有三种可能：
//
//   Empty      从来没放过东西
//   Legitimate 这里有一个有效元素
//   Deleted    这里曾经有元素，被删掉了
//
// **为什么要单独区分 Empty 和 Deleted？**
//
// 因为线性探测的查找过程是"从散列位置往后一格一格找，**遇到 Empty 就停**"。
//
// 如果把删除的格子标成 Empty：
//
//   插入 25、38、51（假设都散列到同一格），它们会依次占据 12、13、14
//   现在删掉 38（下标 13），把它标成 Empty
//   再查 51：从 12 开始，往后走 —— 到 13 发现是 Empty，**以为后面没有了**，
//              于是报告"51 不存在" ✗  但它明明在 14！
//
// 所以删除的格子必须留个"墓碑"（Deleted）：
// 查找时**遇到它要继续往后走**，插入时可以把它当作空位复用。
//
// 这是散列里一个非常经典、也非常容易被忽略的坑。
//
// ============ 表长为什么取素数 ============
//
// 用"除留余数法"（k % TableSize）时，**表长取素数能让分布更均匀**。
//
// 举个反例：表长取 10（合数），关键字是"所有偶数"。
//
//   k % 10 的结果只可能是 0、2、4、6、8 —— **奇数格子全空着**
//
// 如果表长取 11（素数），偶数的余数就能落到所有 11 个格子上。
//
// 直观理解：素数和大多数数都"互质"，不会出现"只能落在某些格子上"的限制。

// 元素类型（关键字）
typedef int ElementType;

// 下标类型
typedef int Index;

// 散列表的最大容量
#define MAXTABLESIZE 20000

// 每格的状态
typedef enum
{
// 从没放过东西
    Empty,
// 有一个有效元素
    Legitimate,
// 被删除了（墓碑）
    Deleted
} EntryType;

// 一个格子
typedef struct HashEntry Cell;
struct HashEntry
{
// 存的关键字
    ElementType Data;
// 这个格子的状态
    EntryType Info;
};

// 散列表
typedef struct TblNode *HashTable;
struct TblNode
{
// 表长
    int TableSize;
// 格子数组
    Cell *Cells;
};

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 表示"没找到"的特殊值
#define NOTFOUND (-1)

// 释放散列表
void DestroyTable(HashTable H)
{
// 空指针不管
    if (H == NULL)
    {
        return;
    }
// 先放格子数组
    free(H->Cells);
// 再放表结构
    free(H);
}

