/* ====================================================================
 *  轮到你了：模块 03  HashMod
 *  作用：最常用的散列函数：关键字直接对表长取余。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */



/* ======== 测试驱动（已给出，可自行修改） ======== */
/* 验证 HashMod 与 HashModScramble */
int main(void)
{
    ElementType keys[] = { 100, 200, 300, 400, 500, 600, 700, 800 };
    int n = 8;
    int size = NextPrime(10);
    int i;
    int hits[64];
    int c1 = 0, c2 = 0;

    printf("关键字都是 10 的倍数，表长 = %d\n\n", size);

    for (i = 0; i < size; i++) hits[i] = 0;
    printf("HashMod（直接取余）：\n");
    for (i = 0; i < n; i++)
    {
        Index h = HashMod(keys[i], size);
        printf("  %d → %d\n", keys[i], h);
        if (hits[h] > 0) c1++;
        hits[h]++;
    }
    printf("  冲突 %d 次，分布: ", c1);
    for (i = 0; i < size; i++) printf("%d ", hits[i]);
    printf("\n\n");

    for (i = 0; i < size; i++) hits[i] = 0;
    printf("HashModScramble（先乘 31 再取余）：\n");
    for (i = 0; i < n; i++)
    {
        Index h = HashModScramble(keys[i], size);
        printf("  %d → %d\n", keys[i], h);
        if (hits[h] > 0) c2++;
        hits[h]++;
    }
    printf("  冲突 %d 次，分布: ", c2);
    for (i = 0; i < size; i++) printf("%d ", hits[i]);
    printf("\n\n");

    printf("对比：打散之后冲突从 %d 次降到 %d 次\n", c1, c2);
    printf("（关键字有规律时，直接取余会让高位差异全丢掉）\n");

    return 0;
}

modes.detail:
// ============ 折叠法（Folding） ============
//
// 适用于**关键字位数很多**的情况，比如一个 12 位身份证号。
//
// 做法：把关键字按位数切段，各段**相加**，再对表长取余。
//
// 举例，关键字 123456789，表长 1000，每段 3 位：
//
//   123 + 456 + 789 = 1368
//   1368 % 1000 = 368
//
// 好处是**每一段的信息都用上了**。如果直接对 123456789 取余，
// 只有低位参与运算，高位的差异全丢了。
//
// 还有一种是"**移位折叠**"：奇数段正着加、偶数段倒着加 ——
// 比直接相加更能打散。
//
// ============ 平方取中法（Mid-Square） ============
//
// 做法：先把关键字**平方**，然后取中间几位。
//
// 举例，关键字 1234，表长 1000：
//
//   1234² = 1522756
//   取中间 3 位 → 227（或者 522，看从哪儿开始取）
//
// 为什么有效？因为**平方之后，原数的每一位都会影响结果的中间位**。
// 这正好弥补了"除留余数法只看低位"的缺点。
//
// 教材上经典的一句话：**"平方取中法对每一位数字都有影响，
// 所以得到的散列地址比较均匀。"**

// 折叠法：按每段 width 位切开，相加后取余
Index HashFold(long long Key, int TableSize, int width)
{
// 累加结果
    long long sum = 0;
// 每一段
    long long part;
// 10^width，用来切段
    long long base = 1;
// 循环用
    int i;

// 先算出 10^width
    for (i = 0; i < width; i++)
    {
        base *= 10;
    }

// 一段一段切，切完就累加
    while (Key > 0)
    {
// 取出最低的 width 位
        part = Key % base;
// 剩下的部分留到下一轮
        Key /= base;
// 累加这一段
        sum += part;
    }

// 对表长取余
    return (Index)(sum % TableSize);
}

// 平方取中法：先平方，再取中间的 digits 位
Index HashMidSquare(long long Key, int TableSize, int digits)
{
// 平方
    long long sq = Key * Key;
// 用来取中间位的除数
    long long base = 1;
// 循环用
    int i;

// 算出 10^digits
    for (i = 0; i < digits; i++)
    {
        base *= 10;
    }

// 先去掉低位的一些位（取中而非取低）
// 这里简化为"去掉最低的 digits/2 位，再取 digits 位"。
    sq /= 10;
    sq = sq % base;

// 最后对表长取余
    return (Index)(sq % TableSize);
}

