{
    long long sum = 0;
    long long part;
    long long base = 1;
    int i;

    for (i = 0; i < width; i++)
    {
        base *= 10;
    }

    while (Key > 0)
    {
        part = Key % base;
        Key /= base;
        sum += part;
    }

    return (Index)(sum % TableSize);
}

Index HashMidSquare(long long Key, int TableSize, int digits)
{
    long long sq = Key * Key;
    long long base = 1;
    int i;

    for (i = 0; i < digits; i++)
    {
        base *= 10;
    }

    sq /= 10;
    sq = sq % base;

    return (Index)(sq % TableSize);
}

