modes.detail:
// ============ 怎么看出差别 ============
//
// 关键是准备一批**有规律的关键字**，让"差的散列函数"暴露问题。
//
// 比如"全是 10 的倍数"这类数据：
//
//   直接取余（表长 10）→ 全挤在 0 号格
//   先乘 31 再取余       → 均匀铺开
//
// 字符串也一样："abc" 和 "cba" 在"求和法"下会撞车，在"移位法"下不会。

// 主函数
int main(void)
{
// 表长：从 10 开始找素数
    int size;
// 循环用
    int i;
// 一组"有规律"的关键字：全是 10 的倍数
    ElementType keys[] = { 100, 200, 300, 400, 500, 600, 700, 800 };
// 关键字个数
    int n = 8;
// 统计每个格子被用到几次
    int hits[64];
// 冲突次数
    int conflict;

// ===== 表长的选择 =====
    printf("=== 表长取素数 ===\n");
    printf("要求表长不小于 10：\n");
    for (i = 10; i <= 14; i++)
    {
        printf("  NextPrime(%d) = %d\n", i, NextPrime(i));
    }
    size = NextPrime(10);
    printf("（素数做表长，除留余数法的分布才均匀）\n\n");

// ===== 对比两种散列函数 =====
    printf("=== 关键字都是 10 的倍数：100, 200, ..., 800 ===\n\n");

// 第一种：直接取余
    printf("--- HashMod（直接取余 k %% %d）---\n", size);
    for (i = 0; i < size; i++)
    {
        hits[i] = 0;
    }
    conflict = 0;
    for (i = 0; i < n; i++)
    {
        Index h = HashMod(keys[i], size);
        if (hits[h] > 0)
        {
            conflict++;
        }
        hits[h]++;
    }
    printf("  散列结果: ");
    for (i = 0; i < n; i++)
    {
        printf("%d→%d  ", keys[i], HashMod(keys[i], size));
    }
    printf("\n");
    printf("  冲突次数: %d\n", conflict);
    printf("  分布: ");
    for (i = 0; i < size; i++)
    {
        printf("%d ", hits[i]);
    }
    printf("\n");
    printf("  （关键字全是 100 的倍数，%d = 1×100，所以余数都有规律）\n\n", size);

// 第二种：先乘 31 再取余
    printf("--- HashModScramble（先乘 31 再取余）---\n");
    for (i = 0; i < size; i++)
    {
        hits[i] = 0;
    }
    conflict = 0;
    for (i = 0; i < n; i++)
    {
        Index h = HashModScramble(keys[i], size);
        if (hits[h] > 0)
        {
            conflict++;
        }
        hits[h]++;
    }
    printf("  散列结果: ");
    for (i = 0; i < n; i++)
    {
        printf("%d→%d  ", keys[i], HashModScramble(keys[i], size));
    }
    printf("\n");
    printf("  冲突次数: %d\n", conflict);
    printf("  分布: ");
    for (i = 0; i < size; i++)
    {
        printf("%d ", hits[i]);
    }
