modes.detail:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ============ 为什么要"状态"而不只是"值" ============
//
// 数组里每格有三种可能：
//
//   Empty      从来没放过东西
//   Legitimate 这里有一个有效元素
//   Deleted    这里曾经有元素，被删掉了
//
// **为什么要单独区分 Empty 和 Deleted？**
//
// 因为线性探测的查找过程是"从散列位置往后一格一格找，**遇到 Empty 就停**"。
//
// 如果把删除的格子标成 Empty：
//
//   插入 25、38、51（假设都散列到同一格），它们会依次占据 12、13、14
//   现在删掉 38（下标 13），把它标成 Empty
//   再查 51：从 12 开始，往后走 —— 到 13 发现是 Empty，**以为后面没有了**，
//              于是报告"51 不存在" ✗  但它明明在 14！
//
// 所以删除的格子必须留个"墓碑"（Deleted）：
// 查找时**遇到它要继续往后走**，插入时可以把它当作空位复用。
//
// 这是散列里一个非常经典、也非常容易被忽略的坑。
//
// ============ 表长为什么取素数 ============
//
// 用"除留余数法"（k % TableSize）时，**表长取素数能让分布更均匀**。
//
// 举个反例：表长取 10（合数），关键字是"所有偶数"。
//
//   k % 10 的结果只可能是 0、2、4、6、8 —— **奇数格子全空着**
//
// 如果表长取 11（素数），偶数的余数就能落到所有 11 个格子上。
//
// 直观理解：素数和大多数数都"互质"，不会出现"只能落在某些格子上"的限制。

// 元素类型（关键字）
typedef int ElementType;

// 下标类型
typedef int Index;

// 散列表的最大容量
#define MAXTABLESIZE 20000

// 每格的状态
typedef enum
{
// 从没放过东西
    Empty,
// 有一个有效元素
    Legitimate,
// 被删除了（墓碑）
    Deleted
} EntryType;

// 一个格子
typedef struct HashEntry Cell;
struct HashEntry
{
// 存的关键字
    ElementType Data;
// 这个格子的状态
    EntryType Info;
};

// 散列表
typedef struct TblNode *HashTable;
struct TblNode
{
// 表长
    int TableSize;
// 格子数组
    Cell *Cells;
};

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 表示"没找到"的特殊值
#define NOTFOUND (-1)

// 释放散列表
void DestroyTable(HashTable H)
{
// 空指针不管
    if (H == NULL)
    {
        return;
    }
// 先放格子数组
    free(H->Cells);
// 再放表结构
    free(H);
}

// ============ 为什么表长要取素数 ============
//
// 因为最常用的散列函数是"除留余数法" `k % TableSize`。
//
// 如果表长是合数，就存在"只能落在部分格子"的问题。
//
//   表长 10，关键字都是偶数 → 只能落在 0 2 4 6 8，一半的格子永远空着
//   表长 12，关键字都是 3 的倍数 → 只能落在 0 3 6 9
//
// 换成素数就没这个问题：素数和大多数数互质，余数能均匀铺开。
//
// ============ 怎么高效地找素数 ============
//
// 试除法：对 p 检查有没有 2 到 √p 之间的因子。
//
// 两个小优化：
//
//   · 从 √p 往下试（因为因子成对出现，试到 √p 就够了）
//   · **只试奇数**：偶数除了 2 都不是素数，所以从 N 往上时直接跳到奇数
//
// 第二个优化很实用：光跳过偶数就省了一半检查。
//
// 复杂度上，试除是 O(√p)，而素数之间的平均间隔是 O(log p)，
// 所以找下一个素数的开销可以接受 —— 而且它只在建表时做一次。

// 取不小于 N 的下一个素数（和 06-01 一样）
int NextPrime(int N)
{
// 循环用
    int i;
// 待检查
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

// 先看 N 本身是不是素数（N 是偶数就先加一到奇数）
    p = (N % 2 != 0) ? N : N + 1;

// 往上找
// 上界要留足余量 —— 否则 p 一超界就直接返回非素数了。
    while (p <= MAXTABLESIZE)
    {
// 从 p/2 往下试除
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }

// 除到 i == 2 都没找到因子，说明 p 是素数
        if (i == 2)
        {
            break;
        }

// 否则试下一个奇数
        p += 2;
    }

// 返回
    return p;
}

// ============ 为什么它最常用 ============
//
//   ① **计算极快**：一次取余运算
//   ② **结果一定在 [0, TableSize) 范围内**：天然就是合法下标
//   ③ 只要表长选得好（素数），分布就很均匀
//
// 这三条让它成了绝大多数实现的选择。
//
// ============ 它适用于什么样的关键字 ============
//
// **随机性比较好**的关键字。
//
// 比如学号、身份证后几位、随机生成的 ID —— 取余之后分布很均匀。
//
// 但如果关键字有"规律"，效果就差：
//
//   全是 10 的倍数（100, 200, 300……）而表长取 10
//   → 余数全是 0，**全挤在一格**
//
// 所以这种情况要先"打散"一下再取余（比如先平方取中、或者乘一个常数）。

// 除留余数法
Index HashMod(ElementType Key, int TableSize)
{
// 直接取余
    return Key % TableSize;
}

// 带打散的除留余数法（用于有规律的关键字）
// 先乘一个与表长互质的常数、再取余，能明显改善分布。
Index HashModScramble(ElementType Key, int TableSize)
{
// 乘一个奇数再取余
// 乘法定理：只要乘数与表长互质，就能保证映射是一一对应的。
    return (Key * 31) % TableSize;
}

// ============ 折叠法（Folding） ============
//
// 适用于**关键字位数很多**的情况，比如一个 12 位身份证号。
//
// 做法：把关键字按位数切段，各段**相加**，再对表长取余。
//
// 举例，关键字 123456789，表长 1000，每段 3 位：
//
//   123 + 456 + 789 = 1368
//   1368 % 1000 = 368
//
// 好处是**每一段的信息都用上了**。如果直接对 123456789 取余，
// 只有低位参与运算，高位的差异全丢了。
//
// 还有一种是"**移位折叠**"：奇数段正着加、偶数段倒着加 ——
// 比直接相加更能打散。
//
// ============ 平方取中法（Mid-Square） ============
//
// 做法：先把关键字**平方**，然后取中间几位。
//
// 举例，关键字 1234，表长 1000：
//
//   1234² = 1522756
//   取中间 3 位 → 227（或者 522，看从哪儿开始取）
//
// 为什么有效？因为**平方之后，原数的每一位都会影响结果的中间位**。
// 这正好弥补了"除留余数法只看低位"的缺点。
//
// 教材上经典的一句话：**"平方取中法对每一位数字都有影响，
// 所以得到的散列地址比较均匀。"**

// 折叠法：按每段 width 位切开，相加后取余
Index HashFold(long long Key, int TableSize, int width)
{
// 累加结果
    long long sum = 0;
// 每一段
    long long part;
// 10^width，用来切段
    long long base = 1;
// 循环用
    int i;

// 先算出 10^width
    for (i = 0; i < width; i++)
    {
        base *= 10;
    }

// 一段一段切，切完就累加
    while (Key > 0)
    {
// 取出最低的 width 位
        part = Key % base;
// 剩下的部分留到下一轮
        Key /= base;
// 累加这一段
        sum += part;
    }

// 对表长取余
    return (Index)(sum % TableSize);
}

// 平方取中法：先平方，再取中间的 digits 位
Index HashMidSquare(long long Key, int TableSize, int digits)
{
// 平方
    long long sq = Key * Key;
// 用来取中间位的除数
    long long base = 1;
// 循环用
    int i;

// 算出 10^digits
    for (i = 0; i < digits; i++)
    {
        base *= 10;
    }

// 先去掉低位的一些位（取中而非取低）
// 这里简化为"去掉最低的 digits/2 位，再取 digits 位"。
    sq /= 10;
    sq = sq % base;

// 最后对表长取余
    return (Index)(sq % TableSize);
}

// ============ 为什么字符串需要特殊处理 ============
//
// 整数可以直接取余，但字符串不行。最直接的想法是"把每个字符的 ASCII 码加起来"：
//
//     h = 0;
//     while (*Key) h += *Key++;
//     return h % TableSize;
//
// 这个办法能用，但**分布很差**。因为加法**满足交换律**：
//
//     "abc" 和 "cba" 的 ASCII 和完全相同 → 散列到同一格
//     "abc" 和 "acb" 也是
//
// 单词里字母的排列组合很多，但"和"相同的却不少 —— 冲突会明显偏多。
//
// ============ 移位相加法 ============
//
// 改良办法是每次**先左移几位再加**：
//
//     h = (h << 5) + *Key++;
//
// 左移 5 位等于乘以 32。这样一来顺序就重要了：
//
//     "abc" → ((0*32 + 97)*32 + 98)*32 + 99
//     "cba" → ((0*32 + 99)*32 + 98)*32 + 97
//
// 两者显然不同了。
//
// 这就是 **Horner 法则**（也就是"秦九韶算法"）—— 把字符串看成
// 一个 32 进制的数，从高位到低位逐位累积。
//
// ============ 几个实用细节 ============
//
// ① **用 unsigned int 而不是 int**：左移和累加会很快溢出，
//    无符号数的溢出是"回绕"，行为有定义；有符号数溢出是未定义行为。
//
// ② 乘数取 31 或 32 是经验值。乘 31 有个额外好处：
//    编译器能优化成 `(h << 5) - h`，比真的乘法快。
//    （Java 的 String.hashCode 用的就是 31。）
//
// ③ 表长仍然应该取素数，配合取余的效果最好。

// 字符串散列：移位相加法
// 乘数是 32（左移 5 位），累积成"32 进制数"。
Index HashString(const char *Key, int TableSize)
{
// 用无符号数，溢出行为有定义
    unsigned int h = 0;

// 逐字符累积
// h = h * 32 + c —— 每一步都把之前所有字符的影响保留下来。
    while (*Key != '\0')
    {
        h = (h << 5) + (unsigned char)(*Key);
        Key++;
    }

// 对表长取余
    return (Index)(h % (unsigned int)TableSize);
}

// 对比用：最简单的"ASCII 求和"散列
// 分布差，但能直观看出"交换律"带来的问题。
Index HashStringBad(const char *Key, int TableSize)
{
// 累加
    unsigned int h = 0;

    while (*Key != '\0')
    {
        h += (unsigned char)(*Key);
        Key++;
    }

    return (Index)(h % (unsigned int)TableSize);
}

// ============ 怎么判断"散列函数好不好" ============
//
// 一个直观的指标：**看各个格子被用到的次数是否均匀**。
//
// 好的散列函数：每个格子被用到的次数差不多。
// 差的散列函数：有的格子挤爆、有的格子永远空着。
//
// 另一种更定量的说法是"**冲突次数**"：
// n 个关键字散列到 m 个格子，理想的冲突次数接近 n²/(2m)。
// 实际冲突数比这个明显大，就说明散列函数有问题。

// 打印散列表的内容
void PrintTable(HashTable H)
{
// 循环用
    int i;

    printf("下标: ");
    for (i = 0; i < H->TableSize; i++)
    {
        printf("%4d", i);
    }
    printf("\n");

    printf("内容: ");
    for (i = 0; i < H->TableSize; i++)
    {
        if (H->Cells[i].Info == Legitimate)
        {
            printf("%4d", H->Cells[i].Data);
        }
        else if (H->Cells[i].Info == Deleted)
        {
            printf("%4s", "X");
        }
        else
        {
            printf("%4s", "-");
        }
    }
    printf("\n");
}

// 统计每种状态各有多少格
void PrintStats(HashTable H)
{
// 循环用
    int i;
// 三种计数
    int empty = 0;
    int used = 0;
    int deleted = 0;

    for (i = 0; i < H->TableSize; i++)
    {
        if (H->Cells[i].Info == Empty)
        {
            empty++;
        }
        else if (H->Cells[i].Info == Legitimate)
        {
            used++;
        }
        else
        {
            deleted++;
        }
    }

    printf("  空 %d 格，有元素 %d 格，墓碑 %d 格\n", empty, used, deleted);
    printf("  装填因子 = %d / %d = %.2f\n", used + deleted, H->TableSize,
           (double)(used + deleted) / H->TableSize);
}

// ============ 怎么看出差别 ============
//
// 关键是准备一批**有规律的关键字**，让"差的散列函数"暴露问题。
//
// 比如"全是 10 的倍数"这类数据：
//
//   直接取余（表长 10）→ 全挤在 0 号格
//   先乘 31 再取余       → 均匀铺开
//
// 字符串也一样："abc" 和 "cba" 在"求和法"下会撞车，在"移位法"下不会。

// 主函数
int main(void)
{
// 表长：从 10 开始找素数
    int size;
// 循环用
    int i;
// 一组"有规律"的关键字：全是 10 的倍数
    ElementType keys[] = { 100, 200, 300, 400, 500, 600, 700, 800 };
// 关键字个数
    int n = 8;
// 统计每个格子被用到几次
    int hits[64];
// 冲突次数
    int conflict;

// ===== 表长的选择 =====
    printf("=== 表长取素数 ===\n");
    printf("要求表长不小于 10：\n");
    for (i = 10; i <= 14; i++)
    {
        printf("  NextPrime(%d) = %d\n", i, NextPrime(i));
    }
    size = NextPrime(10);
    printf("（素数做表长，除留余数法的分布才均匀）\n\n");

// ===== 对比两种散列函数 =====
    printf("=== 关键字都是 10 的倍数：100, 200, ..., 800 ===\n\n");

// 第一种：直接取余
    printf("--- HashMod（直接取余 k %% %d）---\n", size);
    for (i = 0; i < size; i++)
    {
        hits[i] = 0;
    }
    conflict = 0;
    for (i = 0; i < n; i++)
    {
        Index h = HashMod(keys[i], size);
        if (hits[h] > 0)
        {
            conflict++;
        }
        hits[h]++;
    }
    printf("  散列结果: ");
    for (i = 0; i < n; i++)
    {
        printf("%d→%d  ", keys[i], HashMod(keys[i], size));
    }
    printf("\n");
    printf("  冲突次数: %d\n", conflict);
    printf("  分布: ");
    for (i = 0; i < size; i++)
    {
        printf("%d ", hits[i]);
    }
    printf("\n");
    printf("  （关键字全是 100 的倍数，%d = 1×100，所以余数都有规律）\n\n", size);

// 第二种：先乘 31 再取余
    printf("--- HashModScramble（先乘 31 再取余）---\n");
    for (i = 0; i < size; i++)
    {
        hits[i] = 0;
    }
    conflict = 0;
    for (i = 0; i < n; i++)
    {
        Index h = HashModScramble(keys[i], size);
        if (hits[h] > 0)
        {
            conflict++;
        }
        hits[h]++;
    }
    printf("  散列结果: ");
    for (i = 0; i < n; i++)
    {
        printf("%d→%d  ", keys[i], HashModScramble(keys[i], size));
    }
    printf("\n");
    printf("  冲突次数: %d\n", conflict);
    printf("  分布: ");
    for (i = 0; i < size; i++)
    {
        printf("%d ", hits[i]);
    }
    printf("\n");
    printf("  （乘 31 把规律打散了，分布明显更均匀）\n\n");

// ===== 长整数：折叠法 =====
    printf("=== 长整数用折叠法 ===\n");
    {
        long long id = 123456789LL;

        printf("  关键字 = %lld，表长 = %d\n", id, size);
        printf("  直接取余:         %lld %% %d = %d（只有低位参与）\n",
               id, size, (int)(id % size));
        printf("  折叠法（每3位一段）: %d（123+456+789 = 1368，再取余）\n",
               HashFold(id, size, 3));
        printf("  平方取中法:        %d\n", HashMidSquare(id, size, 3));
        printf("  （折叠法让每一段都参与运算，高位的差异不会丢）\n\n");
    }

// ===== 字符串 =====
    printf("=== 字符串散列 ===\n");
    {
        const char *words[] = { "abc", "cba", "bca", "acb", "cab", "bac" };
        int nw = 6;

        printf("  六个字母排列，看两种散列函数的区别：\n\n");
        printf("  %-8s %-14s %-14s\n", "字符串", "ASCII求和法", "移位相加法");
        printf("  -------- -------------- --------------\n");
        for (i = 0; i < nw; i++)
        {
            printf("  %-8s %-14d %-14d\n", words[i],
                   HashStringBad(words[i], size),
                   HashString(words[i], size));
        }
        printf("\n  （求和法下 abc/cba/bca/acb/cab/bac 全都一样 —— 加法满足交换律）\n");
        printf("  （移位相加法把它们分开了 —— 顺序参与运算）\n\n");
    }

// ===== 建一个真的散列表试试 =====
    printf("=== 建一个散列表看看 ===\n");
    {
        HashTable H = (HashTable)malloc(sizeof(struct TblNode));
        int m = NextPrime(10);

        H->TableSize = m;
        H->Cells = (Cell *)malloc(m * sizeof(Cell));
        for (i = 0; i < m; i++)
        {
            H->Cells[i].Info = Empty;
        }

// 用移位法把字符串塞进去（这里用哈希值当关键字）
        for (i = 0; i < n; i++)
        {
            Index h = HashModScramble(keys[i], m);
            int step = 0;
// 线性探测找个空位
            while (H->Cells[(h + step) % m].Info == Legitimate)
            {
                step++;
            }
            H->Cells[(h + step) % m].Data = keys[i];
            H->Cells[(h + step) % m].Info = Legitimate;
        }

        printf("表长 = %d\n", m);
        PrintTable(H);
        PrintStats(H);

        DestroyTable(H);
    }

// 总结
    printf("\n=== 散列函数的设计要点 ===\n");
    printf("  ① 计算要快（除留余数法只有一次取余）\n");
    printf("  ② 结果要在 [0, 表长) 范围内\n");
    printf("  ③ 分布要均匀 —— 表长取素数、关键字有规律时先打散\n");
    printf("  ④ 字符串用移位相加法，不要用简单求和\n");
    printf("\n但无论怎么设计，**冲突都无法完全避免** ——\n");
    printf("下一节就讲冲突了怎么办：开放地址法\n");

// 正常结束
    return 0;
}

modes.short:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>


// 元素类型（关键字）
typedef int ElementType;

// 下标类型
typedef int Index;

// 散列表的最大容量
#define MAXTABLESIZE 20000

// 每格的状态
typedef enum
{
// 从没放过东西
    Empty,
// 有一个有效元素
    Legitimate,
// 被删除了（墓碑）
    Deleted
} EntryType;

// 一个格子
typedef struct HashEntry Cell;
struct HashEntry
{
// 存的关键字
    ElementType Data;
// 这个格子的状态
    EntryType Info;
};

// 散列表
typedef struct TblNode *HashTable;
struct TblNode
{
// 表长
    int TableSize;
// 格子数组
    Cell *Cells;
};

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

// 表示"没找到"的特殊值
#define NOTFOUND (-1)

// 释放散列表
void DestroyTable(HashTable H)
{
// 空指针不管
    if (H == NULL)
    {
        return;
    }
// 先放格子数组
    free(H->Cells);
// 再放表结构
    free(H);
}


// 取不小于 N 的下一个素数（和 06-01 一样）
int NextPrime(int N)
{
// 循环用
    int i;
// 待检查
    int p;

    if (N <= 2)
    {
        return 2;
    }
    if (N <= 3)
    {
        return 3;
    }

// 先看 N 本身是不是素数（N 是偶数就先加一到奇数）
    p = (N % 2 != 0) ? N : N + 1;

// 往上找
    while (p <= MAXTABLESIZE)
    {
// 从 p/2 往下试除
        for (i = (int)(p / 2); i > 2; i--)
        {
            if (p % i == 0)
            {
                break;
            }
        }

// 除到 i == 2 都没找到因子，说明 p 是素数
        if (i == 2)
        {
            break;
        }

// 否则试下一个奇数
        p += 2;
    }

// 返回
    return p;
}


// 除留余数法
Index HashMod(ElementType Key, int TableSize)
{
// 直接取余
    return Key % TableSize;
}

// 带打散的除留余数法（用于有规律的关键字）
Index HashModScramble(ElementType Key, int TableSize)
{
// 乘一个奇数再取余
    return (Key * 31) % TableSize;
}


// 折叠法：按每段 width 位切开，相加后取余
Index HashFold(long long Key, int TableSize, int width)
{
// 累加结果
    long long sum = 0;
// 每一段
    long long part;
// 10^width，用来切段
    long long base = 1;
// 循环用
    int i;

// 先算出 10^width
    for (i = 0; i < width; i++)
    {
        base *= 10;
    }

// 一段一段切，切完就累加
    while (Key > 0)
    {
// 取出最低的 width 位
        part = Key % base;
// 剩下的部分留到下一轮
        Key /= base;
// 累加这一段
        sum += part;
    }

// 对表长取余
    return (Index)(sum % TableSize);
}

// 平方取中法：先平方，再取中间的 digits 位
Index HashMidSquare(long long Key, int TableSize, int digits)
{
// 平方
    long long sq = Key * Key;
// 用来取中间位的除数
    long long base = 1;
// 循环用
    int i;

// 算出 10^digits
    for (i = 0; i < digits; i++)
    {
        base *= 10;
    }

// 先去掉低位的一些位（取中而非取低）
    sq /= 10;
    sq = sq % base;

// 最后对表长取余
    return (Index)(sq % TableSize);
}


// 字符串散列：移位相加法
Index HashString(const char *Key, int TableSize)
{
// 用无符号数，溢出行为有定义
    unsigned int h = 0;

// 逐字符累积
    while (*Key != '\0')
    {
        h = (h << 5) + (unsigned char)(*Key);
        Key++;
    }

// 对表长取余
    return (Index)(h % (unsigned int)TableSize);
}

// 对比用：最简单的"ASCII 求和"散列
Index HashStringBad(const char *Key, int TableSize)
{
// 累加
    unsigned int h = 0;

    while (*Key != '\0')
    {
        h += (unsigned char)(*Key);
        Key++;
    }

    return (Index)(h % (unsigned int)TableSize);
}


